 ['Core Banking','07:15:22','Réussi','Réussi','00:04:32','Réussi'],['Change','07:18:43','Réussi','Réussi','00:03:58','Réussi'],['Paiements','07:21:11','Réussi','Échoué','00:02:10','Échoué'],['Trésorerie','07:22:05','Réussi','Réussi','00:03:45','Réussi'],['Comptabilité','07:23:50','Réussi','Réussi','00:04:01','Réussi'],['RH','07:25:41','Réussi','Réussi','00:03:20','Réussi'],['Marchés','07:27:08','Réussi','Échoué','00:01:58','Échoué'],['AGENCE','07:28:32','Réussi','Réussi','00:02:47','Réussi'],['Audit','07:30:15','Réussi','Réussi','00:03:12','Réussi'],['Data Externe','07:31:26','Réussi','Réussi','00:02:31','Réussi']
